BEGIN;

DROP TABLE IF EXISTS "ProductReservations" CASCADE;
DROP TABLE IF EXISTS "OrderItems" CASCADE;
DROP TABLE IF EXISTS "Orders" CASCADE;
DROP TABLE IF EXISTS "CartItems" CASCADE;
DROP TABLE IF EXISTS "Carts" CASCADE;
DROP TABLE IF EXISTS "Products" CASCADE;
DROP TABLE IF EXISTS "Categories" CASCADE;
DROP TABLE IF EXISTS "Users" CASCADE;
DROP TABLE IF EXISTS "Roles" CASCADE;

CREATE TABLE "Roles" (
    "ID_role" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "title" VARCHAR(50) NOT NULL UNIQUE
);

CREATE TABLE "Users" (
    "ID_user" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "login_user" VARCHAR(50) NOT NULL UNIQUE,
    "password_hash" VARCHAR(256) NOT NULL,
    "role" VARCHAR(50) NOT NULL DEFAULT 'Customer',
    "role_ID" INT NULL DEFAULT 2 REFERENCES "Roles" ("ID_role"),
    "is_active" BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE "Categories" (
    "ID_category" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "title" VARCHAR(100) NOT NULL UNIQUE,
    "CreatedAt" TIMESTAMP NOT NULL DEFAULT (NOW() AT TIME ZONE 'UTC')
);

CREATE TABLE "Products" (
    "ID_product" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "title" VARCHAR(100) NOT NULL,
    "price" NUMERIC(10, 2) NOT NULL CHECK ("price" > 0),
    "category_ID" INT NOT NULL REFERENCES "Categories" ("ID_category"),
    "image_path" VARCHAR(255) NULL,
    "StockQuantity" INT NOT NULL DEFAULT 100,
    "CreatedAt" TIMESTAMP NOT NULL DEFAULT (NOW() AT TIME ZONE 'UTC')
);

CREATE TABLE "Carts" (
    "ID_cart" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "user_ID" INT NOT NULL UNIQUE REFERENCES "Users" ("ID_user")
);

CREATE TABLE "CartItems" (
    "ID_cart_item" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "cart_ID" INT NOT NULL REFERENCES "Carts" ("ID_cart"),
    "product_ID" INT NOT NULL REFERENCES "Products" ("ID_product"),
    "quantity" INT NOT NULL CHECK ("quantity" > 0)
);

CREATE TABLE "Orders" (
    "ID_order" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "user_ID" INT NOT NULL REFERENCES "Users" ("ID_user"),
    "date_order" DATE NOT NULL
);

CREATE TABLE "OrderItems" (
    "ID_order_item" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "order_ID" INT NOT NULL REFERENCES "Orders" ("ID_order"),
    "product_ID" INT NOT NULL REFERENCES "Products" ("ID_product"),
    "quantity" INT NOT NULL CHECK ("quantity" > 0)
);

CREATE TABLE "ProductReservations" (
    "Id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ProductId" INT NOT NULL REFERENCES "Products" ("ID_product") ON DELETE CASCADE,
    "UserId" INT NOT NULL REFERENCES "Users" ("ID_user"),
    "Quantity" INT NOT NULL CHECK ("Quantity" > 0),
    "ReservedAt" TIMESTAMP NOT NULL,
    "IsActive" BOOLEAN NOT NULL
);

